    'ਇਹ ਤੁਹਾਡੇ ਖਾਤੇ ਅਤੇ ਸਮੱਗਰੀ ਨੂੰ ਸਥਾਈ ਤੌਰ \'ਤੇ ਮਿਟਾਉਣ ਦੀ ਸਮਾਂ-ਸਾਰਣੀ ਕਰਦਾ ਹੈ। ਇਹ ਤੁਰੰਤ ਨਹੀਂ ਹੈ: ਇੱਕ ਸਰਵਰ ਕਾਰਜ ਤੁਹਾਡੀ ਬੇਨਤੀ ਦੇ ਲਗਭਗ 30 ਦਿਨਾਂ ਬਾਅਦ ਮਿਟਾਉਣ ਨੂੰ ਅੰਤਿਮ ਰੂਪ ਦੇ ਸਕਦਾ ਹੈ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਰੱਦ ਨਹੀਂ ਕਰਦੇ। ਤੁਸੀਂ ਉਸ ਅੰਤਮ ਤਾਰੀਖ ਤੋਂ ਪਹਿਲਾਂ ਦੁਬਾਰਾ ਸਾਈਨ ਇਨ ਕਰ ਸਕਦੇ ਹੋ ਅਤੇ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਰੱਦ ਕਰ ਸਕਦੇ ਹੋ। ਇੱਕ ਵਾਰ ਪ੍ਰਕਿਰਿਆ ਹੋਣ ਤੋਂ ਬਾਅਦ, ਇਸਨੂੰ ਅਣਕੀਤਾ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।',
